  value: BlaxelSandboxIdentity,
  request?: CreateOptions,
): SandboxInfo {
  const mapped = generatedMapSandboxIdentity(value);
  const id = mapped.id ?? request?.name ?? value.metadata?.name ?? "";
  const result: SandboxInfo = {
    id,
    provider: "blaxel",
